import { restoreSession, rpc, ApiError } from "../account/supabase-client.js";
import { DEFAULT_LANGUAGES, MAX_LANGUAGES, humanMic, maxSeatsForQueue, queueOptionLabel, queuesForExperience, validateDraft } from "./domain.js";
import { resolvePlayTogetherStartup } from "./startup.js";
import { legacyAccountHandoffUrl } from "../account/testing-auth-handoff.js";
import { createStatusMessage } from "./status-message.js";

const $=id=>document.getElementById(id);
const message=createStatusMessage($("pageMessage"));
let catalog=null,dashboard=null,matches=[],flow="NEED_PLAYERS",draftInvitees=[],draftGuests=[];
const hidden=(id,value)=>{$(id).hidden=value;};
const text=(tag,className,value)=>{const node=document.createElement(tag);if(className)node.className=className;node.textContent=value;return node;};
const button=(label,action,className="secondary")=>{const node=text("button",className,label);node.type="button";node.addEventListener("click",action);return node;};
const row=(title,detail,...actions)=>{const node=document.createElement("div");node.className="pt-list-row";const copy=document.createElement("div");copy.append(text("strong","",title),text("span","",detail));const controls=document.createElement("div");controls.className="pt-row-actions";controls.append(...actions);node.append(copy,controls);return node;};
const one=result=>Array.isArray(result)?result[0]:result;
const displayError=error=>{
 const code=`${error?.code||""} ${error?.message||""}`;
 const known={ACTIVE_INTENT_EXISTS:"You already have an active Play Together intent.",ACTIVE_SESSION_EXISTS:"You already have an active Play Together intent.",INVALID_SEATS_WANTED:"Seats Wanted exceeds this queue's verified limit.",QUEUE_NOT_AVAILABLE:"That queue is not available for creation.",COMPLETE_TEAM_REQUIRED:"Team vs Team requires a complete verified-size team.",AVOID_LIMIT_REACHED:"You can avoid at most two players per game.",MATCH_NOT_ELIGIBLE:"That session is no longer eligible.",STALE_REQUEST:"That request changed. Refresh and try again.",READY_CHECK_CLOSED:"Ready Check has closed."};
 return Object.entries(known).find(([key])=>code.includes(key))?.[1]||error?.message||"Something went wrong.";
};
function showMain(){hidden("loadingPanel",true);hidden("authPanel",true);hidden("loadErrorPanel",true);hidden("createPanel",!!dashboard.active_session);hidden("activePanel",!dashboard.active_session);hidden("avoidPanel",false);hidden("historyPanel",false);}
async function loadCatalog(){const result=await rpc("get_play_together_catalog");return one(result)?.catalog||one(result);}
async function loadDashboard(){return one(await rpc("get_play_together_dashboard"));}
async function refresh(){dashboard=await loadDashboard();showMain();renderInvitations();renderAvoids();renderHistory();if(dashboard.active_session)await renderActive();else renderCreate();}
function option(select,value,label,disabled=false){const node=document.createElement("option");node.value=value;node.textContent=label;node.disabled=disabled;select.append(node);}

function renderCatalog(){
 const exp=$("experienceSelect"),region=$("regionSelect"),languages=$("languageChoices");exp.replaceChildren();region.replaceChildren();languages.replaceChildren();
 option(exp,"","Choose an experience");for(const item of catalog.experiences)option(exp,item.key,item.name);
 option(region,"","Choose a Riot region/server");for(const item of catalog.regions)option(region,item.key,`${item.name} · ${item.platform_id}`);
 for(const language of catalog.languages){const label=document.createElement("label"),input=document.createElement("input");input.type="checkbox";input.name="language";input.value=language.key;input.checked=DEFAULT_LANGUAGES.includes(language.key);input.addEventListener("change",()=>{const selected=[...document.querySelectorAll('input[name="language"]:checked')];if(selected.length>MAX_LANGUAGES){input.checked=false;message("Choose no more than two languages.");}});label.append(input,document.createTextNode(language.name));languages.append(label);}
 renderQueues();renderPositions();
}
function selectedQueue(){return catalog?.queues.find(item=>item.key===$("queueSelect").value)||null;}
function renderQueues(){const select=$("queueSelect");select.replaceChildren();option(select,"","Choose a mode / queue");for(const queue of queuesForExperience(catalog,$("experienceSelect").value))option(select,queue.key,queueOptionLabel(queue),!queue.enabled);renderQueueRules();renderPositions();}
function renderPositions(){const experience=$("experienceSelect").value,available=(catalog?.positions||[]).filter(p=>!p.experience_key||p.experience_key===experience);for(const id of ["positionSelect","guestPosition"]){const select=$(id);select.replaceChildren();option(select,"","No preference");for(const item of available)option(select,item.key,item.name);}hidden("positionLabel",!available.length);}
function plannedSize(){return 1+draftInvitees.length+draftGuests.length;}
function renderQueueRules(){
 const queue=selectedQueue(),seats=$("seatsSelect");seats.replaceChildren();
 if(!queue){seats.disabled=true;option(seats,"","Choose a queue first");$("queueNote").textContent="";$("seatsHelp").textContent="Choose a queue first.";return;}
 $("queueNote").textContent=`${queue.availability} · Rule ${queue.rule_version}. ${queue.note}`;
 const current=plannedSize(),max=maxSeatsForQueue(queue,current),usesSeats=flow==="NEED_PLAYERS";hidden("seatsLabel",!usesSeats);seats.disabled=!usesSeats||max<1;option(seats,"",usesSeats?"Choose seats":"Not applicable");if(usesSeats)for(let i=1;i<=max;i++)option(seats,String(i),String(i));
 $("seatsHelp").textContent=flow==="TEAM_VS_TEAM"?`A complete team of ${queue.team_size||"verified size"} is required.`:usesSeats?`Current planned group: ${current}. You may ask for 1–${max} additional player${max===1?"":"s"}.`:"Find Squad searches existing hosts; it does not use Seats Wanted.";
}
function setFlow(next){flow=next;for(const node of document.querySelectorAll("[data-flow]"))node.classList.toggle("is-active",node.dataset.flow===flow);const meta={NEED_PLAYERS:["NEED PLAYERS","Create your squad"],FIND_SQUAD:["FIND SQUAD","Find an open host"],TEAM_VS_TEAM:["TEAM VS TEAM","Find an opponent squad"]}[flow];$("flowEyebrow").textContent=meta[0];$("flowTitle").textContent=meta[1];renderQueueRules();updateCreateButton();}
function updateCreateButton(){const timing=document.querySelector('input[name="timingKind"]:checked')?.value||"PLAY_NOW";$("createButton").textContent=`${flow==="FIND_SQUAD"?"START":flow==="TEAM_VS_TEAM"?"FIND OPPONENT":"CREATE"} ${timing.replace("_"," ")} INTENT`;}
function renderDraftMembers(){const list=$("draftMemberList");list.replaceChildren();for(const member of draftInvitees)list.append(row(`@${member.gamid_handle}`,`${member.display_name} · Invitation required`,button("REMOVE",()=>{draftInvitees=draftInvitees.filter(x=>x.entity_id!==member.entity_id);renderDraftMembers();})));for(const guest of draftGuests)list.append(row(guest.name,`Guest · Manual / Unverified${guest.position_key?` · ${guest.position_key}`:""}`,button("REMOVE",()=>{draftGuests=draftGuests.filter(x=>x!==guest);renderDraftMembers();})));renderQueueRules();}
function renderCreate(){
 hidden("lastSetupButton",!dashboard.last_setup);setFlow(flow);renderDraftMembers();
}
function fillLastSetup(){const last=dashboard.last_setup;if(!last)return;const exp=catalog.queues.find(q=>q.key===last.queue_key)?.experience_key;$("experienceSelect").value=exp||last.experience_key;renderQueues();$("queueSelect").value=last.queue_key;renderQueueRules();$("regionSelect").value=last.region_key;$("positionSelect").value=last.position_key||"";for(const input of document.querySelectorAll('input[name="language"]'))input.checked=(last.language_keys||[]).includes(input.value);const mic=document.querySelector(`input[name="mic"][value="${last.mic_preference}"]`);if(mic)mic.checked=true;message("Last setup loaded. Review and edit before creating.",true);}
async function searchMembers(query,target,action){target.replaceChildren();if(query.trim().replace(/^@/,"").length<3)return;try{const rows=await rpc("search_play_together_members",{candidate_query:query});for(const member of rows||[])target.append(row(`@${member.gamid_handle}`,member.display_name,button(action.label,()=>action.run(member))));}catch(error){message(displayError(error));}}
function renderInvitations(){const list=$("invitationList"),items=dashboard.invitations||[];hidden("invitationPanel",!items.length);list.replaceChildren();for(const invite of items)list.append(row(`@${invite.owner_handle} invited you`,`${invite.queue_name} · ${invite.region_name}`,button("ACCEPT",()=>respondInvitation(invite.session_id,true),"primary compact"),button("DECLINE",()=>respondInvitation(invite.session_id,false),"secondary compact")));}
async function respondInvitation(sessionId,accept){try{await rpc("respond_play_together_invitation",{candidate_session_id:sessionId,candidate_accept:accept});await refresh();message(accept?"Invitation accepted.":"Invitation declined.",true);}catch(error){message(displayError(error));}}
function statusLabel(value){return String(value||"").replaceAll("_"," ");}
async function renderActive(){
 const s=dashboard.active_session,languageNames=new Map(catalog.languages.map(x=>[x.key,x.name]));$("activeIntent").textContent=statusLabel(s.intent);$("activeHeading").textContent=statusLabel(s.status);$("activeTiming").textContent=statusLabel(s.session_kind);
 const details=[["Game","League of Legends"],["Experience",s.experience_name],["Mode / Queue",s.queue_name],["Riot region",s.region_name],["Group",s.group_kind],["Confirmed",s.current_group_size],["Seats wanted",s.intent==="NEED_PLAYERS"?`${s.seats_filled}/${s.seats_wanted}`:"Not applicable"],["Languages",(s.language_keys||[]).map(k=>languageNames.get(k)||k).join(", ")],["Mic",humanMic(s.mic_preference)],["Timing",s.scheduled_start_at?new Date(s.scheduled_start_at).toLocaleString():"Play Now"],["Rule",s.rule_version]];
 const dl=$("activeDetails");dl.replaceChildren();for(const [term,value] of details){const wrap=document.createElement("div");wrap.append(text("dt","",term),text("dd","",String(value)));dl.append(wrap);}
 const members=$("memberList");members.replaceChildren();for(const m of dashboard.members||[])members.append(row(m.member_kind==="GUEST"?m.guest_name:`@${m.handle}`,`${m.member_kind==="GUEST"?"Guest · Manual / Unverified":m.display_name} · ${statusLabel(m.membership_status)} · ${m.side}`));
 const matching=["MATCHING","REQUEST_PENDING"].includes(s.status),isOwner=s.creator_entity_id===dashboard.my_entity.entity_id;hidden("matchingSection",!matching||s.intent==="NEED_PLAYERS");hidden("requestSection",!matching||!["NEED_PLAYERS","TEAM_VS_TEAM"].includes(s.intent));hidden("readySection",s.status!=="READY_CHECK");hidden("scheduledSection",s.status!=="AWAITING_START");hidden("roomSection",!["ROOM_OPEN","IN_PLAY"].includes(s.status));$("cancelButton").hidden=!["GROUP_FORMING","MATCHING","REQUEST_PENDING","AWAITING_START","READY_CHECK"].includes(s.status);$("cancelButton").textContent=isOwner?"CANCEL ACTIVE INTENT":"LEAVE ACTIVE SQUAD";$("cancelButton").dataset.action=isOwner?"cancel":"leave";
 if(matching&&s.intent!=="NEED_PLAYERS")await loadMatches();renderRequests();renderReady();if(dashboard.room){$("startPlayButton").hidden=dashboard.room.room_status!=="OPEN";$("completeButton").hidden=!['OPEN','IN_PLAY'].includes(dashboard.room.room_status);}
}
async function loadMatches(){const list=$("matchList");list.replaceChildren(text("p","pt-help","Loading compatible sessions…"));try{matches=await rpc("get_play_together_matches",{candidate_session_id:dashboard.active_session.session_id})||[];list.replaceChildren();if(!matches.length)list.append(text("p","pt-empty","No compatible open sessions yet."));for(const item of matches)list.append(row(`@${item.owner_handle} · ${item.owner_name}`,`${statusLabel(item.intent)} · group ${item.group_size} · score ${item.compatibility_score}`,button("REQUEST HOST",()=>requestHost(item.session_id),"primary compact")));}catch(error){list.replaceChildren(text("p","pt-empty",displayError(error)));}}
async function requestHost(hostSessionId){try{await rpc("request_play_together_host",{candidate_applicant_session_id:dashboard.active_session.session_id,candidate_host_session_id:hostSessionId});await refresh();message("Request sent for host approval.",true);}catch(error){message(displayError(error));}}
function renderRequests(){const list=$("requestList");list.replaceChildren();const requests=dashboard.incoming_requests||[];if(!requests.length)list.append(text("p","pt-empty","No pending requests."));for(const request of requests)list.append(row(`@${request.owner_handle} · ${request.owner_name}`,`Group of ${request.group_size}`,button("APPROVE",()=>respondRequest(request.request_id,true),"primary compact"),button("REJECT",()=>respondRequest(request.request_id,false),"secondary compact")));}
async function respondRequest(requestId,approve){try{await rpc("respond_play_together_request",{candidate_request_id:requestId,candidate_approve:approve});await refresh();message(approve?"Request approved.":"Request rejected.",true);}catch(error){message(displayError(error));}}
function renderReady(){const list=$("readyList");list.replaceChildren();if(!dashboard.ready_check)return;$("readyDeadline").textContent=`Respond before ${new Date(dashboard.ready_check.deadline_at).toLocaleTimeString()}. Accepted is not Ready.`;for(const response of dashboard.ready_responses||[]){const canAnswer=response.entity_id===dashboard.my_entity.entity_id||response.represented_by_entity_id===dashboard.my_entity.entity_id;const actions=response.response==="PENDING"&&canAnswer?[button("READY",()=>respondReady(response.member_id,true),"primary compact"),button("DECLINE",()=>respondReady(response.member_id,false),"secondary compact")]:[];list.append(row(response.guest_name||response.display_name,statusLabel(response.response),...actions));}}
async function respondReady(memberId,ready){try{const result=await rpc("respond_play_together_ready",{candidate_member_id:memberId,candidate_ready:ready});await refresh();message(one(result)==="ROOM_OPEN"?"Everyone is ready. GamID Session Room opened.":ready?"Ready confirmed.":"Ready Check declined.",true);}catch(error){message(displayError(error));}}
function renderAvoids(){const list=$("avoidList");list.replaceChildren();for(const item of dashboard.avoids||[])list.append(row(`@${item.handle}`,item.name,button("REMOVE",()=>setAvoid(item.entity_id,false),"secondary compact")));}
async function setAvoid(entityId,active){try{await rpc("set_play_together_avoid",{candidate_avoided_entity_id:entityId,candidate_game_key:"league_of_legends",candidate_active:active});await refresh();message(active?"Player added to Avoid Playing With.":"Player removed from Avoid Playing With.",true);}catch(error){message(displayError(error));}}
function renderHistory(){const list=$("historyList");list.replaceChildren();const history=dashboard.history||[];if(!history.length)list.append(text("p","pt-empty","No completed Play Together history yet."));for(const item of history)list.append(row(statusLabel(item.intent),`${item.queue_name} · ${item.region_name} · ${statusLabel(item.status)}`));for(const person of dashboard.played_with||[])list.append(row(`Played with @${person.handle}`,person.name));}
async function createAttempt(event){event.preventDefault();const queue=selectedQueue(),groupKind=document.querySelector('input[name="groupKind"]:checked').value,timingKind=document.querySelector('input[name="timingKind"]:checked').value,languageKeys=[...document.querySelectorAll('input[name="language"]:checked')].map(x=>x.value),scheduledStart=timingKind==="SCHEDULED"?$("scheduledStart").value:null;const draft={flow,groupKind,currentGroupSize:plannedSize(),queue,regionKey:$("regionSelect").value,seatsWanted:flow==="NEED_PLAYERS"?Number($("seatsSelect").value):0,languageKeys,micPreference:document.querySelector('input[name="mic"]:checked').value,timingKind,scheduledStart,horizonMinutes:Number(catalog.settings?.scheduled_horizon_minutes||180)};const error=validateDraft(draft);if(error){message(error);return;}$("createButton").disabled=true;try{await rpc("create_play_together_attempt",{candidate_intent:flow,candidate_group_kind:groupKind,candidate_queue_key:queue.key,candidate_region_key:draft.regionKey,candidate_seats_wanted:draft.seatsWanted,candidate_language_keys:languageKeys,candidate_mic_preference:draft.micPreference,candidate_session_kind:timingKind,candidate_scheduled_start_at:scheduledStart?new Date(scheduledStart).toISOString():null,candidate_position_key:$("positionSelect").value||null,candidate_invited_entity_ids:draftInvitees.map(x=>x.entity_id),candidate_guests:draftGuests.map(x=>({name:x.name,position_key:x.position_key||null,game_data:{verification:"MANUAL_UNVERIFIED"}}))});draftInvitees=[];draftGuests=[];await refresh();message("Play Together intent created.",true);}catch(err){message(displayError(err));}finally{$("createButton").disabled=false;}}
async function cancelActive(){try{const leaving=$("cancelButton").dataset.action==="leave";await rpc(leaving?"leave_play_together":"cancel_my_play_together_session",{candidate_session_id:dashboard.active_session.session_id});await refresh();message(leaving?"You left the active squad.":"Active intent cancelled. You can create another one.",true);}catch(error){message(displayError(error));}}
async function roomAction(action){try{await rpc("advance_play_together_room",{candidate_session_id:dashboard.active_session.session_id,candidate_action:action});await refresh();message(action==="START"?"Play started.":"Session completed and saved to history.",true);}catch(error){message(displayError(error));}}

for(const node of document.querySelectorAll("[data-flow]"))node.addEventListener("click",()=>setFlow(node.dataset.flow));
$("experienceSelect").addEventListener("change",renderQueues);$("queueSelect").addEventListener("change",renderQueueRules);$("createForm").addEventListener("submit",createAttempt);$("lastSetupButton").addEventListener("click",fillLastSetup);$("cancelButton").addEventListener("click",cancelActive);$("refreshMatchesButton").addEventListener("click",loadMatches);$("retryButton").addEventListener("click",()=>location.reload());$("startPlayButton").addEventListener("click",()=>roomAction("START"));$("completeButton").addEventListener("click",()=>roomAction("COMPLETE"));
for(const input of document.querySelectorAll('input[name="groupKind"]'))input.addEventListener("change",()=>{hidden("groupBuilder",input.value!=="US"||!input.checked);if(input.checked&&input.value==="ME"){draftInvitees=[];draftGuests=[];renderDraftMembers();}});
for(const input of document.querySelectorAll('input[name="timingKind"]'))input.addEventListener("change",()=>{if(input.checked){hidden("scheduledLabel",input.value!=="SCHEDULED");updateCreateButton();}});
let memberTimer,avoidTimer;$("memberSearch").addEventListener("input",()=>{clearTimeout(memberTimer);memberTimer=setTimeout(()=>searchMembers($("memberSearch").value,$("memberSearchResults"),{label:"ADD",run:member=>{if(!draftInvitees.some(x=>x.entity_id===member.entity_id)){draftInvitees.push(member);renderDraftMembers();}$("memberSearchResults").replaceChildren();}}),250);});
$("avoidSearch").addEventListener("input",()=>{clearTimeout(avoidTimer);avoidTimer=setTimeout(()=>searchMembers($("avoidSearch").value,$("avoidSearchResults"),{label:"AVOID",run:member=>setAvoid(member.entity_id,true)}),250);});
$("addGuestButton").addEventListener("click",()=>{const name=$("guestName").value.trim();if(!name){message("Enter the guest's name.");return;}draftGuests.push({name,position_key:$("guestPosition").value||null});$("guestName").value="";renderDraftMembers();});
$("beginReadyButton").addEventListener("click",async()=>{try{await rpc("begin_scheduled_ready_check",{candidate_session_id:dashboard.active_session.session_id});await refresh();}catch(error){message(displayError(error));}});

(async()=>{const startup=await resolvePlayTogetherStartup({restoreSession,loadAuthenticated:async()=>{const loadedCatalog=await loadCatalog();if(!loadedCatalog)throw new ApiError("Play Together catalog is unavailable.",500,"CATALOG_UNAVAILABLE");return {catalog:loadedCatalog,dashboard:await loadDashboard()};}});if(startup.state==="AUTH_REQUIRED"){const handoffUrl=legacyAccountHandoffUrl(location);if(handoffUrl){location.replace(handoffUrl);return;}hidden("loadingPanel",true);hidden("authPanel",false);return;}if(startup.state==="LOAD_ERROR"){hidden("loadingPanel",true);hidden("loadErrorPanel",false);message(displayError(startup.error));return;}catalog=startup.value.catalog;dashboard=startup.value.dashboard;renderCatalog();showMain();renderInvitations();renderAvoids();renderHistory();if(dashboard.active_session)await renderActive();else renderCreate();})();
